CREATE OR REPLACE FUNCTION public.set_task_status(p_task_id uuid, p_status text)
 RETURNS tasks
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t public.tasks%ROWTYPE; next_due timestamptz; step interval;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 IF p_status NOT IN ('open','completed','cancelled','deferred') THEN RAISE EXCEPTION 'Invalid status'; END IF;
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id AND owner_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
 IF p_status='deferred' AND t.recurrence_rule IS NULL THEN RAISE EXCEPTION 'Only recurring tasks can be deferred'; END IF;
 IF t.status IS DISTINCT FROM p_status THEN
  UPDATE public.tasks SET status=p_status,completed_at=CASE WHEN p_status='completed' THEN now() ELSE NULL END,updated_at=now() WHERE id=p_task_id RETURNING * INTO t;
  IF p_status='completed' AND t.reward_coins>0 THEN
   INSERT INTO public.reward_ledger(task_id,owner_id,coins_delta,reason) VALUES(p_task_id,auth.uid(),t.reward_coins,'task_completed')
   ON CONFLICT(task_id) WHERE reason='task_completed' DO NOTHING;
  ELSE
   DELETE FROM public.reward_ledger WHERE task_id=p_task_id AND reason='task_completed' AND owner_id=auth.uid();
  END IF;
  IF p_status IN ('completed','deferred') AND t.recurrence_rule IN ('daily','weekly') THEN
   step:=CASE t.recurrence_rule WHEN 'weekly' THEN interval '7 days' ELSE interval '1 day' END;
   next_due:=((t.due_at AT TIME ZONE 'America/New_York')+step) AT TIME ZONE 'America/New_York';
   WHILE next_due<=now() LOOP
    next_due:=((next_due AT TIME ZONE 'America/New_York')+step) AT TIME ZONE 'America/New_York';
   END LOOP;
   INSERT INTO public.tasks(title,status,due_at,recurrence_rule,recurrence_series_id,reward_coins,owner_id,instructions,task_origin,difficulty,activity_id)
   VALUES(t.title,'open',next_due,t.recurrence_rule,t.recurrence_series_id,t.reward_coins,auth.uid(),t.instructions,t.task_origin,t.difficulty,t.activity_id)
   ON CONFLICT(recurrence_series_id,due_at) WHERE recurrence_series_id IS NOT NULL DO NOTHING;
  END IF;
 END IF;
 RETURN t;
END;$function$

CREATE OR REPLACE FUNCTION public.complete_task_with_notes(p_task_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS tasks
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t public.tasks%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 SELECT * INTO t FROM public.tasks WHERE id=p_task_id AND owner_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
 IF t.status='completed' THEN
  UPDATE public.tasks SET completion_notes=NULLIF(BTRIM(p_notes),'') WHERE id=p_task_id RETURNING * INTO t;
  RETURN t;
 END IF;
 IF t.status<>'open' THEN RAISE EXCEPTION 'Only open tasks can be completed'; END IF;
 UPDATE public.tasks SET completion_notes=NULLIF(BTRIM(p_notes),''),updated_at=now() WHERE id=p_task_id;
 RETURN public.set_task_status(p_task_id,'completed');
END;$function$

CREATE OR REPLACE FUNCTION public.beehive_start_timer(p_seconds integer, p_label text DEFAULT 'Timer'::text)
 RETURNS beehive_timers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid := auth.uid(); created public.beehive_timers;
begin
 if u is null then raise exception 'Not signed in'; end if;
 if p_seconds is null or p_seconds < 10 or p_seconds > 86400 then raise exception 'Duration must be between 10 seconds and 24 hours'; end if;
 if trim(coalesce(p_label,''))='' or length(trim(p_label))>120 then raise exception 'Timer name must be 1-120 characters'; end if;
 insert into public.beehive_timers(owner_id,label,duration_seconds,due_at)
 values (u,trim(p_label),p_seconds,now()+make_interval(secs=>p_seconds))
 returning * into created;
 return created;
exception when unique_violation then raise exception 'Finish or cancel your current timer first';
end;
$function$

CREATE OR REPLACE FUNCTION public.beehive_cancel_timer(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid := auth.uid(); cancelled uuid;
begin
 if u is null then raise exception 'Not signed in'; end if;
 update public.beehive_timers set status='cancelled',updated_at=now(),lease_until=null
 where id=p_id and owner_id=u and status in ('pending','sending')
 returning id into cancelled;
 return cancelled is not null;
end;
$function$

