CREATE OR REPLACE FUNCTION public.kae_comfort_ledger_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_delta integer;
begin
 if new.reason='task_completed' and new.coins_delta>0 then v_delta:=new.coins_delta;
 elsif new.reason like 'shop_purchase:%' and new.coins_delta<0 then v_delta:=-new.coins_delta;
 else return new; end if;
 update public.pet_state set comfort_value=least(100,greatest(0,coalesce(comfort_value,100)-greatest(0,extract(epoch from (now()-coalesce(comfort_updated_at,now()))))/7200)+v_delta),comfort_updated_at=now() where owner_id=new.owner_id;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_catalog_task_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if new.activity_id is null then return new; end if;
 if new.status='completed' and (tg_op='INSERT' or old.status is distinct from 'completed') then
  insert into public.activity_log(owner_id,activity_id,task_id,outcome,notes,happened_at)
  values(new.owner_id,new.activity_id,new.id,'completed',new.completion_notes,coalesce(new.completed_at,now()))
  on conflict(task_id) where outcome='completed' and task_id is not null do update set happened_at=excluded.happened_at,notes=excluded.notes;
 elsif tg_op='UPDATE' and old.status='completed' and new.status<>'completed' then
  delete from public.activity_log where task_id=new.id and outcome='completed';
 elsif tg_op='UPDATE' and new.status='completed' and old.status='completed' then
  update public.activity_log set notes=new.completion_notes where task_id=new.id and outcome='completed';
 end if;
 return new;
end $function$
